import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import {
  Hash,
  LockingScript,
  P2PKH,
  PrivateKey,
  Secp256r1,
  Signature,
  BigNumber,
  Transaction,
  Utils
} from '@bsv/sdk'
import * as R1Comb from '../R1Comb.js'
import { R1CombError } from '../R1Comb.js'

/**
 * R1Comb is a consensus contract: these tests hold it byte-identical to the
 * code the BSV Wallet Vault spends with (@bsv/expo-wallet-toolbox
 * core/services/vault/r1comb.ts).
 *
 * - vectors.json was generated by that module (with @noble/curves). See
 *   test/vectors/r1comb/README.md.
 * - The two .hex files are a lock and its spend mined on testnet.
 */
const DIR = join(__dirname, '../../test/vectors/r1comb')
const V = JSON.parse(readFileSync(join(DIR, 'vectors.json'), 'utf8'))
const FIXTURE_LOCK_HEX = readFileSync(
  join(DIR, '51c53430fe63108a2a1ddd231253df069fb424cc6f1bb0ee60b4b07792d3579a_0.hex'),
  'utf8'
).trim()
const FIXTURE_TX_HEX = readFileSync(
  join(DIR, '476611a431172df767a73349522536fa78d63a83b560efbb695b853bf60b4b80.hex'),
  'utf8'
).trim()
const FIXTURE_Q = '03f4d667712d8825372cd616b0b1b1a818e5eeb3681dd45c5bdd59fed9f21d5a7d'
const FIXTURE_SATS = 4600
const FIXTURE_DIGEST = '0e6232f57f4f48a6c7455ba872b07c8542558403c9bbd4470eed83087d4dd90b'
const FIXTURE_R = 0xe3c4329684a494d2db1c99234f136d9b941c4274f40befe976b546c130f9f7c7n
const FIXTURE_S = 0x401a6223caf9c7b57188e354044d52687ed2c69f975bc4c075369d44199d67e9n

const hex = (a: number[]): string => Utils.toHex(a)
const sha = (a: number[]): string => Utils.toHex(Hash.sha256(a))
const fromScriptNum = (b: number[]): bigint => {
  const le = [...b].reverse()
  const neg = (le[0] & 0x80) !== 0
  le[0] &= 0x7f
  const v = BigInt('0x' + (Utils.toHex(le) || '0'))
  return neg ? -v : v
}

jest.setTimeout(120_000)

describe('R1Comb: byte-identical to the BSV Wallet Vault', () => {
  it('geometry and sizes', () => {
    expect([R1Comb.COMB_ROWS, R1Comb.COMB_COLS, R1Comb.TABLE_SIZE]).toEqual([6, 43, 32])
    expect([1, 2, 3, 4, 5].map(n => R1Comb.R1C_LOCK_LEN(n))).toEqual([
      45199, 45225, 45250, 45275, 45300
    ])
    expect(() => R1Comb.R1C_LOCK_LEN(6)).toThrow(R1CombError)
    expect([...R1Comb.R1C_VERIFY_FLAGS]).toEqual([
      'MINIMALDATA',
      'UTXO_AFTER_CHRONICLE',
      'SIGHASH_FORKID',
      'STRICTENC',
      'CLEANSTACK',
      'SIGPUSHONLY',
      'LOW_S'
    ])
  })

  it('shared suffix, mixed-add script and G table', () => {
    const suffix = R1Comb.sharedSuffix()
    expect({ length: suffix.length, sha256: sha(suffix) }).toEqual(V.sharedSuffix)
    expect(sha(R1Comb.completeMixedAddScript())).toBe(V.completeMixedAddScriptSha256)
    expect(sha(R1Comb.gTable().flatMap(({ x, y }) => [...R1Comb.le33(x), ...R1Comb.le33(y)]))).toBe(
      V.gTableSha256
    )
  })

  it('key encodings, comb tables and commitments', () => {
    for (const k of V.keys) {
      expect(R1Comb.compressPubkey(k.uncompressed)).toBe(k.compressed)
      expect(sha(R1Comb.canonicalTableBytes(k.compressed))).toBe(k.canonicalTableSha256)
      expect(R1Comb.commitment(k.compressed, k.salt)).toBe(k.commitment)
    }
    for (const a of V.compressAccepts) expect(R1Comb.compressPubkey(a.input)).toBe(a.output)
  })

  it('refuses every key encoding the Vault refuses', () => {
    for (const r of V.compressRejects) {
      expect(r.error).not.toBeNull()
      expect(() => R1Comb.compressPubkey(r.input)).toThrow(R1CombError)
    }
  })

  it('locks for N = 1..5', () => {
    for (const l of V.locks) {
      const bin = R1Comb.buildLock({
        commitments: l.commitments,
        saltHex64: V.keys[0].salt
      }).toBinary()
      expect(bin).toHaveLength(l.length)
      expect(hex(bin.slice(0, 400))).toBe(l.head)
      expect(sha(bin)).toBe(l.sha256)
      expect(R1Comb.bakedCommitments(LockingScript.fromBinary(bin))).toEqual(l.commitments)
    }
  })

  it('preimages, signatures and unlocks for N = 1..5, from either DER form', () => {
    V.spends.forEach((sp: any, i: number) => {
      const l = V.locks[i]
      const lock = R1Comb.buildLock({ commitments: l.commitments, saltHex64: V.keys[0].salt })
      const src = new Transaction(1, [], [{ lockingScript: lock, satoshis: sp.sourceSatoshis }], 0)
      const tx = new Transaction(
        1,
        [{ sourceTransaction: src, sourceOutputIndex: 0, sequence: sp.sequence }],
        [
          {
            lockingScript: new P2PKH().lock(new PrivateKey('11'.repeat(32), 16).toAddress()),
            satoshis: 90_000
          }
        ],
        sp.lockTime
      )
      expect(sha(src.toBinary())).toBe(sp.sourceSha256)
      const pre = R1Comb.sighashPreimage(tx, 0, sp.sourceSatoshis)
      expect(hex(pre)).toBe(sp.preimage)
      expect(R1Comb.signerDigest(pre)).toBe(sp.digest)
      expect(R1Comb.pushTxSignatureS(pre).toString(16)).toBe(sp.pushTxS)
      expect(R1Comb.pushTxDerCheck(pre).ok).toBe(sp.pushTxOk)
      const key = V.keys[sp.signer]
      const { r, s } = R1Comb.decodeDerSignature(Utils.toArray(sp.derLow, 'hex'))
      expect(
        R1Comb.fullR({ preimage: pre, rSig: r, s, pubkeyHex33: key.compressed })!.toString(16)
      ).toBe(sp.fullR)
      for (const der of [sp.derLow, sp.derHigh]) {
        const unlock = R1Comb.buildUnlock({
          preimage: pre,
          derSig: Utils.toArray(der, 'hex'),
          pubkeyHex33: key.compressed,
          saltHex64: key.salt
        })
        expect(unlock.toHex()).toBe(sp.unlockLow)
        tx.inputs[0].unlockingScript = unlock
        expect(sha(tx.toBinary())).toBe(sp.txSha256)
        expect(
          R1Comb.verifyVaultInput({
            tx,
            inputIndex: 0,
            sourceSatoshis: sp.sourceSatoshis,
            lockingScript: lock,
            unlockingScript: unlock
          })
        ).toBe(true)
      }
    })
  })

  it('recode and script numbers', () => {
    for (const r of V.recode) expect(R1Comb.recode(BigInt('0x' + r.u)).toString(16)).toBe(r.out)
    for (const n of V.scriptNum) expect(hex(R1Comb.encNum(BigInt(n.v)))).toBe(n.enc)
  })
})

describe('R1Comb: the testnet fixture', () => {
  const fixtureLock = LockingScript.fromHex(FIXTURE_LOCK_HEX)
  const tx = Transaction.fromHex(FIXTURE_TX_HEX)
  const unlock = tx.inputs[0].unlockingScript!

  it('comb tables equal the mined lock', () => {
    const g = R1Comb.gTable()
    const q = R1Comb.combTable(FIXTURE_Q)
    for (let j = 0; j < 32; j++) {
      expect(hex(fixtureLock.chunks[87 + 2 * j].data!)).toBe(hex(R1Comb.scriptNum(g[j].x)))
      expect(hex(fixtureLock.chunks[88 + 2 * j].data!)).toBe(hex(R1Comb.scriptNum(g[j].y)))
      expect(hex(fixtureLock.chunks[151 + 2 * j].data!)).toBe(hex(R1Comb.scriptNum(q[j].x)))
      expect(hex(fixtureLock.chunks[152 + 2 * j].data!)).toBe(hex(R1Comb.scriptNum(q[j].y)))
    }
  })

  it('the mined spend validates under the strict flags; one satoshi more does not', () => {
    const preimage = R1Comb.sighashPreimage(tx, 0, FIXTURE_SATS)
    expect(R1Comb.signerDigest(preimage)).toBe(FIXTURE_DIGEST)
    const args = { tx, inputIndex: 0, lockingScript: fixtureLock, unlockingScript: unlock }
    expect(R1Comb.verifyVaultInput({ ...args, sourceSatoshis: FIXTURE_SATS })).toBe(true)
    expect(() => R1Comb.verifyVaultInput({ ...args, sourceSatoshis: FIXTURE_SATS + 1 })).toThrow()
    const r = fromScriptNum(unlock.chunks[0].data!)
    expect(r).toBe(FIXTURE_R)
    expect(fromScriptNum(unlock.chunks[1].data!)).toBe(FIXTURE_S)
    expect(R1Comb.fullR({ preimage, rSig: r, s: FIXTURE_S, pubkeyHex33: FIXTURE_Q })).toBe(r)
  })
})

describe('R1Comb: round trip with an @bsv/sdk P-256 key', () => {
  it('a 2-of-N lock spends with either key and refuses a stranger', () => {
    const curve = new Secp256r1()
    const priv = [
      curve.generatePrivateKeyHex(),
      curve.generatePrivateKeyHex(),
      curve.generatePrivateKeyHex()
    ]
    const pub = priv.map(d => curve.pointToHex(curve.publicKeyFromPrivate(d), true))
    const salt = '5a'.repeat(32)
    const lock = R1Comb.buildLock({
      commitments: pub.slice(0, 2).map(p => R1Comb.commitment(p, salt)),
      saltHex64: salt
    })
    for (const signer of [0, 1, 2]) {
      const src = new Transaction(1, [], [{ lockingScript: lock, satoshis: 50_000 }], 0)
      const tx = new Transaction(
        1,
        [{ sourceTransaction: src, sourceOutputIndex: 0, sequence: 0xffffffff }],
        [
          {
            lockingScript: new P2PKH().lock(new PrivateKey('22'.repeat(32), 16).toAddress()),
            satoshis: 40_000
          }
        ]
      )
      const pre = R1Comb.sighashPreimage(tx, 0, 50_000)
      const sig = curve.sign(
        Uint8Array.from(Utils.toArray(R1Comb.signerDigest(pre), 'hex')),
        priv[signer],
        { prehashed: true }
      )
      const der = new Signature(
        new BigNumber(sig.r, 16),
        new BigNumber(sig.s, 16)
      ).toDER() as number[]
      const unlockingScript = R1Comb.buildUnlock({
        preimage: pre,
        derSig: der,
        pubkeyHex33: pub[signer],
        saltHex64: salt
      })
      const spend = () =>
        R1Comb.verifyVaultInput({
          tx,
          inputIndex: 0,
          sourceSatoshis: 50_000,
          lockingScript: lock,
          unlockingScript
        })
      if (signer < 2) expect(spend()).toBe(true)
      else expect(spend).toThrow()
    }
  })
})
